197→// writeCommittedMain writes metadata entries to the /main ref.
198→// This includes session metadata and prompts — but NOT the raw transcript
199→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
200→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
201→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
202→	if err := validateWriteOpts(opts); err != nil {
203→		return 0, err
204→	}
205→
206→	refName := plumbing.ReferenceName(paths.V2MainRefName)
207→	if err := s.ensureRef(refName); err != nil {
208→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
209→	}
210→
211→	parentHash, rootTreeHash, err := s.getRefState(refName)
212→	if err != nil {
213→		return 0, err
214→	}
215→
216→	basePath := opts.CheckpointID.Path() + "/"
217→	checkpointPath := opts.CheckpointID.Path()
218→
219→	// Read existing entries at this checkpoint's shard path
220→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
221→	if err != nil {
222→		return 0, err
223→	}
224→
225→	// Build main session entries (metadata, prompts — no transcript or content hash)
226→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
227→	if err != nil {
228→		return 0, err
229→	}
230→
231→	// Splice entries into root tree
232→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
233→	if err != nil {
234→		return 0, err
235→	}
236→
237→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
238→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
239→		return 0, err
240→	}
241→	return sessionIndex, nil
242→}
