244→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
245→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
246→// Returns the session index used, for coordination with writeCommittedFullTranscript.
247→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
248→	// Read existing summary to get current session count
249→	var existingSummary *CheckpointSummary
250→	metadataPath := basePath + paths.MetadataFileName
251→	if entry, exists := entries[metadataPath]; exists {
252→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
253→		if err == nil {
254→			existingSummary = existing
255→		}
256→	}
257→
258→	// Determine session index
259→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
260→
261→	// Write session files (metadata and prompts — no transcript or content hash)
262→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
263→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
264→	if err != nil {
265→		return 0, err
266→	}
267→
268→	// Build the sessions array
269→	var sessions []SessionFilePaths
270→	if existingSummary != nil {
271→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
272→		copy(sessions, existingSummary.Sessions)
273→	} else {
274→		sessions = make([]SessionFilePaths, 1)
275→	}
276→	sessions[sessionIndex] = sessionFilePaths
277→
278→	// Write root CheckpointSummary
279→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
280→		return 0, err
281→	}
282→	return sessionIndex, nil
283→}
284→
285→// writeMainSessionToSubdirectory writes a single session's metadata, prompts, and
286→// content hash to a session subdirectory (0/, 1/, 2/, … indexed by session order
287→// within the checkpoint). Unlike the v1 equivalent, this does NOT write the raw
288→// transcript (full.jsonl) — that goes to /full/current.
289→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
290→	filePaths := SessionFilePaths{}
291→
292→	// Clear existing entries at this session path
293→	for key := range entries {
294→		if strings.HasPrefix(key, sessionPath) {
295→			delete(entries, key)
296→		}
297→	}
298→
299→	// Write prompts
300→	if len(opts.Prompts) > 0 {
301→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
302→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
303→		if err != nil {
304→			return filePaths, err
305→		}
306→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
307→			Name: sessionPath + paths.PromptFileName,
308→			Mode: filemode.Regular,
309→			Hash: blobHash,
310→		}
311→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
312→	}
313→
314→	// Write session metadata
315→	sessionMetadata := CommittedMetadata{
316→		CheckpointID:                opts.CheckpointID,
317→		SessionID:                   opts.SessionID,
318→		Strategy:                    opts.Strategy,
319→		CreatedAt:                   time.Now().UTC(),
320→		Branch:                      opts.Branch,
321→		CheckpointsCount:            opts.CheckpointsCount,
322→		FilesTouched:                opts.FilesTouched,
323→		Agent:                       opts.Agent,
324→		Model:                       opts.Model,
325→		TurnID:                      opts.TurnID,
326→		IsTask:                      opts.IsTask,
327→		ToolUseID:                   opts.ToolUseID,
328→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
329→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
330→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart,
331→		TokenUsage:                  opts.TokenUsage,
332→		SessionMetrics:              opts.SessionMetrics,
333→		InitialAttribution:          opts.InitialAttribution,
334→		Summary:                     redactSummary(opts.Summary),
335→		CLIVersion:                  versioninfo.Version,
336→	}
337→
338→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
339→	if err != nil {
340→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
341→	}
342→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
343→	if err != nil {
344→		return filePaths, err
345→	}
346→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
347→		Name: sessionPath + paths.MetadataFileName,
348→		Mode: filemode.Regular,
349→		Hash: metadataHash,
350→	}
351→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
352→
353→	return filePaths, nil
354→}
