899→		if otherShadow == shadowBranchName && state.StepCount > 0 {
900→			// Another session still needs this shadow branch
901→			return nil
902→		}
903→	}
904→
905→	// No other sessions need it, delete the shadow branch via CLI
906→	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
907→	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
908→		// Branch already gone is not an error
909→		if errors.Is(err, ErrBranchNotFound) {
910→			return nil
911→		}
912→		return fmt.Errorf("failed to remove shadow branch: %w", err)
913→	}
914→	return nil
